"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[82480],{3331:(e,r,t)=>{t.d(r,{R:()=>o,x:()=>a});var n=t(36672);const s={},i=n.createContext(s);function o(e){const r=n.useContext(i);return n.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),n.createElement(i.Provider,{value:r},e.children)}},82218:(e,r,t)=>{t.r(r),t.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>k,frontMatter:()=>o,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"2023/04/13","title":"2023-04-13","description":"Semaphore: Et tastatur for hele kroppen","source":"@site/i18n/nb/docusaurus-plugin-content-docs/current/2023/04/13.md","sourceDirName":"2023/04","slug":"/2023/04/13","permalink":"/nb/2023/04/13","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/nb/docusaurus-plugin-content-docs//current/2023/04/13.md","tags":[],"version":"current","frontMatter":{"localized_date":"13. april 2023","top_news":"Semaphore: Et tastatur for hele kroppen"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-14","permalink":"/nb/2023/04/14"},"next":{"title":"2023-04-12","permalink":"/nb/2023/04/12"}}');var s=t(23420),i=t(3331);const o={localized_date:"13. april 2023",top_news:"Semaphore: Et tastatur for hele kroppen"},a="2023-04-13",l={},d=[{value:"Semaphore: Et tastatur for hele kroppen",id:"semaphore-et-tastatur-for-hele-kroppen",level:2},{value:"Vis GPT-4-drevne netts\xf8k for utviklere",id:"vis-gpt-4-drevne-netts\xf8k-for-utviklere",level:2},{value:"Erstattet bestevennene mine med en LLM trent p\xe5 500k gruppechat-meldinger",id:"erstattet-bestevennene-mine-med-en-llm-trent-p\xe5-500k-gruppechat-meldinger",level:2},{value:"NPR slutter p\xe5 Twitter etter \xe5 ha blitt stemplet som &quot;statstilknyttede medier&quot;.",id:"npr-slutter-p\xe5-twitter-etter-\xe5-ha-blitt-stemplet-som-statstilknyttede-medier",level:2},{value:"Masseoppsigelser og frav\xe6rende sjefer skaper en moralsk krise i Meta.",id:"masseoppsigelser-og-frav\xe6rende-sjefer-skaper-en-moralsk-krise-i-meta",level:2},{value:"Hetzner introduserer ARM64 Cloud Servers",id:"hetzner-introduserer-arm64-cloud-servers",level:2},{value:"Ny NASA-direkt\xf8r sverger ed p\xe5 Carl Sagans &quot;Pale Blue Dot&quot; i stedet for Bibelen.",id:"ny-nasa-direkt\xf8r-sverger-ed-p\xe5-carl-sagans-pale-blue-dot-i-stedet-for-bibelen",level:2},{value:"Intel Foundry Services og Arm kunngj\xf8r samarbeid om SoC-design",id:"intel-foundry-services-og-arm-kunngj\xf8r-samarbeid-om-soc-design",level:2},{value:"EVE Online-spiller bruker obskur regel for \xe5 gjennomf\xf8re det st\xf8rste kuppet i spillhistorien.",id:"eve-online-spiller-bruker-obskur-regel-for-\xe5-gjennomf\xf8re-det-st\xf8rste-kuppet-i-spillhistorien",level:2},{value:"Virtuelle tr\xe5der ankommer i JDK 21, og innleder en ny \xe6ra med samtidighet",id:"virtuelle-tr\xe5der-ankommer-i-jdk-21-og-innleder-en-ny-\xe6ra-med-samtidighet",level:2}];function m(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(r.header,{children:(0,s.jsx)(r.h1,{id:"2023-04-13",children:"2023-04-13"})}),"\n",(0,s.jsx)(r.h2,{id:"semaphore-et-tastatur-for-hele-kroppen",children:"Semaphore: Et tastatur for hele kroppen"}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://github.com/everythingishacked/Semaphore",children:"Original"}),'.\nSemaphore er et fullkroppstastatur som bruker OpenCV og MediaPipes Pose-deteksjon for \xe5 oppdage kroppsmerker fra videoinngang, beregne relative forskjeller og oversette dem til taster og kommandoer som sendes via tastaturet. Den prim\xe6re inngangen er \xe5 "skrive" bokstaver, sifre og symboler via flaggsemafor ved \xe5 strekke ut begge armene i forskjellige vinkler, med andre modifiserende bevegelser inkludert for funksjoner som shift, backspace og piltaster. Den kj\xf8rer p\xe5 det nyeste MacOS og kan n\xe5s via terminalen ved hjelp av et tilpasset tastaturbibliotek.']}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35536550",children:"Discussion Service"}),".\nEt tastatursystem kalt Semaphore, som bruker fysiske bevegelser, har f\xe5tt positive tilbakemeldinger fra Discussion Service-brukere og har implikasjoner for fjernarbeidere som \xf8nsker \xe5 kombinere fysisk trening og programmering. Brukerne diskuterer \xe5 kombinere Semaphore med stenografi, musikknoter, yoga\xf8velser og programmering, og noen p\xe5peker potensialet for \xf8kt effektivitet ved \xe5 legge til funksjoner som autofullf\xf8ring."]}),"\n",(0,s.jsx)(r.h2,{id:"vis-gpt-4-drevne-netts\xf8k-for-utviklere",children:"Vis GPT-4-drevne netts\xf8k for utviklere"}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.phind.com",children:"Original"}),'.\nNettstedet "phind.com" er for \xf8yeblikket utilgjengelig, ettersom det bruker en sikkerhetstjeneste for \xe5 beskytte seg mot nettangrep som kan ha blitt utl\xf8st av visse handlinger, for eksempel innsending av et bestemt ord eller uttrykk, en SQL-kommando eller feilaktige data. For \xe5 l\xf8se dette kan brukerne sende en e-post til nettstedets eier og inkludere detaljer om hva de gjorde da blokkeringen skjedde, og Cloudflare Ray-ID-en som finnes nederst p\xe5 siden.']}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35543668",children:"Discussion Service"}),".\nPhind.coms GPT-4-drevne s\xf8kemotor tilbyr presise kodesvar og detaljerte forklaringer gjennom tilpassede filtre, og inntektsdelingsmodeller har blitt utforsket for innholdsprodusenter, selv om det er bekymringer om modelleringskostnader; brukere har rost tjenesten for dens klare informasjon, effektivitet og verdifulle tilleggsinformasjon, selv om noen problemer med sp\xf8rringsn\xf8yaktighet har blitt notert. Noen brukere har kritisert GPT-4s evne til \xe5 l\xf8se problemer og har stilt sp\xf8rsm\xe5l ved n\xf8yaktigheten og relevansen, men Phind-teamet har svart ved \xe5 lansere en ny versjon med en ekspertmodusfunksjon."]}),"\n",(0,s.jsx)(r.h2,{id:"erstattet-bestevennene-mine-med-en-llm-trent-p\xe5-500k-gruppechat-meldinger",children:"Erstattet bestevennene mine med en LLM trent p\xe5 500k gruppechat-meldinger"}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.izzy.co/blogs/robo-boys.html",children:"Original"}),".\nEn LLM ble trent p\xe5 Izzy Millers usensurerte gruppechatmeldinger fra college-tiden, noe som resulterte i bedre samtaler med hans beste venner. Datasettet besto av 500 000 meldinger, og Miller sesjonerte det for enklere modellering. Den resulterende modellen genererte hele samtaler og fanget den kontekstuelle essensen av gruppechatten, og artikkelen forklarer hvordan man konverterer LLaMA-vekter til et format som er kompatibelt med Transformers-biblioteket ved hjelp av Python-koding, inkludert viktigheten av riktig diskplassforsyning."]}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35540154",children:"Discussion Service"}),".\nNoen Discussion Service-brukere uttrykker bekymring for de etiske implikasjonene av \xe5 lage digitale kopier av enkeltpersoner ved hjelp av personopplysninger, mens andre hevder at eksisterende lover og moralsk/sosialt press fortsatt gjelder. Kritikere advarer mot potensielle skadelige anvendelser av LLM-teknologi av autokratiske regimer eller for profittdrevne form\xe5l. Splittende debatter om AI-teknologi har dukket opp med bekymringer om dens upr\xf8vde innvirkning p\xe5 personvernet og hyperskepsis rundt dens effektivitet. Det er kontroverser rundt bruken av AI-chatbots og deres potensial til \xe5 erstatte menneskelige forbindelser, samt etiske bekymringer om tekstutfyllingsverkt\xf8y som gj\xf8r det mulig \xe5 lage digitale simuleringer av tapte kj\xe6re."]}),"\n",(0,s.jsx)(r.h2,{id:"npr-slutter-p\xe5-twitter-etter-\xe5-ha-blitt-stemplet-som-statstilknyttede-medier",children:'NPR slutter p\xe5 Twitter etter \xe5 ha blitt stemplet som "statstilknyttede medier".'}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.wbur.org/npr/1169269161/npr-leaves-twitter-government-funded-media-label",children:"Original"}),'.\nNPR stoppet sin Twitter-aktivitet etter at Twitter merket dem som "statstilknyttede medier", en merkelapp NPR mener er un\xf8yaktig og misvisende. Denne beslutningen beskytter NPRs troverdighet og sikrer at de kan produsere journalistikk uten negativitet. Elon Musk innr\xf8mmet at han kan ha tatt feil med etiketten og kan endre den til "offentlig finansiert.".']}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35539280",children:"Discussion Service"}),'.\nNPR m\xf8tte kritikk og sluttet til slutt p\xe5 Twitter etter \xe5 ha blitt merket som "statstilknyttede medier" p\xe5 grunn av statlig finansiering, noe som f\xf8rte til en debatt om kriteriene for slik merking og om det n\xf8yaktig karakteriserer NPR som en nyhetsorganisasjon med redaksjonell uavhengighet. Noen Discussion Service-brukere antyder at andre selskaper, inkludert Elon Musks selskaper, faller inn under denne kategorien p\xe5 grunn av statlig finansiering. Kommentarene fremhever ogs\xe5 det komplekse forholdet mellom mediekanaler, finansieringskilder og redaksjonell uavhengighet, der noen anklager NPR for \xe5 v\xe6re venstrevridd, mens andre forsvarer deres \xe5penhet og uavhengighet.']}),"\n",(0,s.jsx)(r.h2,{id:"masseoppsigelser-og-frav\xe6rende-sjefer-skaper-en-moralsk-krise-i-meta",children:"Masseoppsigelser og frav\xe6rende sjefer skaper en moralsk krise i Meta."}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.nytimes.com/2023/04/12/technology/meta-layoffs-employees-management.html",children:"Original"}),".\nMoralen er nede hos Facebooks morselskap, Meta, p\xe5 grunn av masseoppsigelser og frav\xe6rende sjefer som skaper bekymring blant de ansatte. De ansatte setter ogs\xe5 sp\xf8rsm\xe5lstegn ved selskapets retning."]}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35537813",children:"Discussion Service"}),".\nEksperter diskuterer ulike meninger om fremtiden for banebrytende teknologier som generativ AI, VR og kryptovaluta. Mens noen tar til orde for spesifikke bruksomr\xe5der for generativ KI og fremskritt innen generative medier, er det bekymringer knyttet til potensialet for \xe5 automatisere middelklassejobber og n\xf8yaktigheten til generative KI-modeller. Bedrifter ser p\xe5 generativ AI for \xe5 f\xe5 fart p\xe5 markedet for AR/VR-teknologi, og suksessen til Meta Labs' enheter st\xe5r i kontrast til den usikre suksessen til Apples headset. Kryptoindustrien blir sett p\xe5 som en affinitetssvindel av noen, men Bitcoin blir fortsatt sett p\xe5 annerledes av andre."]}),"\n",(0,s.jsx)(r.h2,{id:"hetzner-introduserer-arm64-cloud-servers",children:"Hetzner introduserer ARM64 Cloud Servers"}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.hetzner.com/press-release/arm64-cloud/",children:"Original"}),".\nDen tyske hosting- og skyleverand\xf8ren Hetzner har lansert fire nye Hetzner Cloud-servere basert p\xe5 Arm64-teknologi, som markerer selskapets f\xf8rste bruk av prosessorene. Serverne tilbyr opptil 16 vCPU-er og kombineres med opptil 32 GB ECC-RAM og opptil 320 GB NVMe SSD-basert lagring. Den nye serverlinjen starter til en pris p\xe5 \u20ac 3,79 ($ 4,54) per m\xe5ned, og har faktureringsalternativer per time som vil redusere kostnadene for kundene."]}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35540084",children:"Discussion Service"}),".\nHetzner har gitt ut ARM64 skyservere som er billigere og overg\xe5r AWS. Skyinfrastruktur har blandede meninger, ettersom noen argumenterer for p\xe5litelighet og skalerbarhet, mens andre synes enklere oppsett er mer p\xe5litelige og kostnadseffektive. Hetzners tilbud fyller et hull for de som \xf8nsker \xe5 kj\xf8re Docker uten \xe5 konfigurere alle tjenestene, men det er kanskje ikke egnet for sikkerhetsbevisste selskaper p\xe5 grunn av svakere fysisk tilgangskontroll. Noen har rapportert om kontoforbud p\xe5 grunn av Hetzners strenge svindelpolitikk, og det er sp\xf8rsm\xe5l om b\xe6rekraften til lave priser i Europa p\xe5 grunn av h\xf8ye energikostnader."]}),"\n",(0,s.jsx)(r.h2,{id:"ny-nasa-direkt\xf8r-sverger-ed-p\xe5-carl-sagans-pale-blue-dot-i-stedet-for-bibelen",children:'Ny NASA-direkt\xf8r sverger ed p\xe5 Carl Sagans "Pale Blue Dot" i stedet for Bibelen.'}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.independent.co.uk/space/nasa-director-carl-sagan-oath-b2317698.html",children:"Original"}),'.\nMakenzie Lystrup, den nyutnevnte direkt\xf8ren for NASAs Goddard Space Flight Center, har avlagt en ukonvensjonell ed ved \xe5 bruke Carl Sagans bok "Pale Blue Dot" fra 1994 i stedet for Bibelen. Astronomens bok var inspirert av det ber\xf8mte Pale Blue Dot-fotografiet av Jorden tatt i 1990 av romsonden Voyager 1, og Lystrup hevder \xe5 v\xe6re "sterkt fokusert p\xe5 \xe5 utvikle neste generasjon innovat\xf8rer". Goddard Space Flight Centers arbeidsstyrke best\xe5r av 10 000 ansatte, b\xe5de tjenestemenn og kontrakt\xf8rer, og senteret er ansvarlig for \xe5 gjennomf\xf8re en portef\xf8lje p\xe5 4 milliarder dollar.']}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35536612",children:"Discussion Service"}),'.\nDen nye NASA-direkt\xf8ren sverget p\xe5 Carl Sagans "Pale Blue Dot", noe som utl\xf8ste en debatt om effektiviteten av eder, betydningen av hellige tekster, personlige verdier versus religi\xf8se tekster og den sanne betydningen av personlig ansvar. Noen hevder at det er mer hensiktsmessig \xe5 sverge p\xe5 en bok som representerer ens verdier, mens andre mener det er n\xf8dvendig \xe5 ha en representasjon av en guddom som garantist for eden. Sverging har rituelle funksjoner og har blitt brukt til \xe5 forme samfunn og historie, men til syvende og sist inneholder artikkelen ingen ny eller spennende informasjon for eksperter p\xe5 omr\xe5det.']}),"\n",(0,s.jsx)(r.h2,{id:"intel-foundry-services-og-arm-kunngj\xf8r-samarbeid-om-soc-design",children:"Intel Foundry Services og Arm kunngj\xf8r samarbeid om SoC-design"}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.intel.com/content/www/us/en/newsroom/news/intel-foundry-arm-announce-multigeneration-collaboration-leading-edge-soc-design.html",children:"Original"}),".\nIntel Foundry Services (IFS) og Arm har blitt enige om et flergenerasjonssamarbeid for \xe5 muliggj\xf8re utvikling av system-on-chips (SoC) med lavt str\xf8mforbruk for mobile enheter og andre bransjer. Samarbeidet vil kombinere Arms sikre og energieffektive prosessorer med IFS' produksjonskapasitet i USA og EU, noe som vil gi nye banebrytende transistorteknologier for forbedret effekt og ytelse p\xe5 Intel 18A-prosessen. Dette samarbeidet vil muliggj\xf8re en mer balansert global forsyningskjede for st\xf8perikunder som arbeider med mobil SoC-design p\xe5 Arm-baserte CPU-kjerner."]}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35539057",children:"Discussion Service"}),".\nIntel Foundry Services samarbeider med Arm om \xe5 designe SoC-er, og m\xf8ter konkurranse fra TSMC som har en historie med samarbeid med Arm. Discussion Service-brukere diskuterer fordeler og ulemper med Mac Studio og sammenligner det med andre PC-alternativer, med kritikk av Macs begrensninger for spill og CAD-programvare. Artikkelen og kommentarene dekker alternativer for IOT-enheter og produksjon, Intels 2nm nodeproduksjon og spekulasjoner om Intels evne til \xe5 levere p\xe5 l\xf8ftene sine, samtidig som de anerkjenner viktigheten av str\xf8mforbruk, pris og tr\xe5dl\xf8s kapasitet i utviklingen av IOT-enheter."]}),"\n",(0,s.jsx)(r.h2,{id:"eve-online-spiller-bruker-obskur-regel-for-\xe5-gjennomf\xf8re-det-st\xf8rste-kuppet-i-spillhistorien",children:"EVE Online-spiller bruker obskur regel for \xe5 gjennomf\xf8re det st\xf8rste kuppet i spillhistorien."}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.pcgamer.com/eve-online-player-uses-obscure-rule-to-pull-off-the-biggest-heist-in-the-games-history/",children:"Original"}),'.\nEn EVE Online-spiller har gjennomf\xf8rt det st\xf8rste kuppet i spillhistorien ved \xe5 utnytte "aksjemekanikeren", noe som resulterte i en fangst p\xe5 over 22 300 dollar i ekte penger. Dette innebar \xe5 ta kontroll over Event Horizon Expeditionaries ved hjelp av en ren konto, overf\xf8re aksjer og t\xf8mme selskapets lommebok for 130 milliarder ISK og flere skip, og den totale verdien av utbyttet ansl\xe5s til 2,23 billioner ISK. Aksjesystemet er potensielt for enkelt \xe5 utnytte, if\xf8lge en Reddit-tr\xe5d fra 2014, og denne strategien har blitt testet f\xf8r.']}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35533711",children:"Discussion Service"}),".\nEn spiller orkestrerte et vellykket ran i EVE Online, noe som reiste sp\xf8rsm\xe5l rundt selskapets mekanikk og spillets utnyttelsesrisiko. Ranet ble sett p\xe5 som kult og et h\xf8ydepunkt i spillet, men noen kritiserer spillets \xf8konomiske fokus og mekanikk, inkludert verdien av valutaen i spillet og selskapets stemmesystem."]}),"\n",(0,s.jsx)(r.h2,{id:"virtuelle-tr\xe5der-ankommer-i-jdk-21-og-innleder-en-ny-\xe6ra-med-samtidighet",children:"Virtuelle tr\xe5der ankommer i JDK 21, og innleder en ny \xe6ra med samtidighet"}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"https://www.infoq.com/news/2023/04/virtual-threads-arrives-jdk21/",children:"Original"}),".\nN/A."]}),"\n",(0,s.jsxs)(r.p,{children:[(0,s.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35535906",children:"Discussion Service"}),".\nJDK 21s virtuelle tr\xe5der reduserer fysiske tr\xe5der for samtidighet og forenkling av io-intensive applikasjoner, men debatter om minneh\xe5ndtering oppst\xe5r. Java sammenlignes med Go, og rammeverk som Spring, Spring Boot og Quarkus gir alternativer til Ruby on Rails, mens debatten om Java versus Go vurderer ytelse, observerbarhet, soliditet av typesystemer og interop. Artikkelen reflekterer over nisjekategorien JVM og hvordan ulike implementasjoner kan p\xe5virke brukeropplevelsen, med sammenligninger med C# og JetBrains Rider nevnt."]})]})}function k(e={}){const{wrapper:r}={...(0,i.R)(),...e.components};return r?(0,s.jsx)(r,{...e,children:(0,s.jsx)(m,{...e})}):m(e)}}}]);